// nutricional.jsx — Lista nutricional para operacional (leitura) e admin/vet
import React from 'react';
import { TopBar, HorseAvatar } from './screens';

export function NutricionalScreen({ setScreen, cavalos, insumos, currentUser }) {
  const getIns = (id) => insumos.find(i => i.id === id) || { nome: id, unidade: '' };

  return (
    <div style={{ paddingBottom: 90 }}>
      <TopBar
        title="Lista Nutricional"
        subtitle="Atualizada automaticamente"
      />

      <div style={{ padding: '12px 20px 0' }}>
        {cavalos.map(c => {
          const n = c.nutricao || {};
          const racao = n.racaoId ? getIns(n.racaoId) : null;
          const sups = (n.suplementos || []).map(s => ({ ...s, ins: getIns(s.insumoId) }));
          const temDieta = racao || n.oleoMlDia > 0 || sups.length > 0;

          return (
            <div key={c.id} style={{
              background: 'var(--card)', border: '1px solid var(--line)',
              borderRadius: 16, padding: '14px 16px', marginBottom: 12,
            }}>
              {/* Cabeçalho do cavalo */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: temDieta ? 12 : 0 }}>
                <HorseAvatar cavalo={c} size={40} />
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 16, fontWeight: 700, fontFamily: 'var(--serif)', color: 'var(--ink)' }}>
                    {c.nome}
                  </div>
                  <div style={{ fontSize: 11, color: 'var(--ink-3)' }}>
                    {c.baia} · {Array.isArray(c.categoria) ? c.categoria.join(', ') : c.categoria}
                  </div>
                </div>
                {(currentUser?.role === 'admin' || currentUser?.role === 'vet') && (
                  <button
                    onClick={() => setScreen('editarCavalo')}
                    style={{
                      background: 'var(--soft)', border: '1px solid var(--line)',
                      borderRadius: 8, padding: '5px 10px', fontSize: 11,
                      color: 'var(--accent)', fontWeight: 600, cursor: 'pointer',
                      fontFamily: 'var(--sans)',
                    }}
                  >
                    Editar
                  </button>
                )}
              </div>

              {/* Dieta */}
              {temDieta && (
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {racao && (
                    <NutriChip label="Ração" value={`${racao.nome} · ${n.racaoKgDia} kg/dia`} cor="#a16207" />
                  )}
                  {n.oleoMlDia > 0 && (
                    <NutriChip label="Óleo" value={`${n.oleoMlDia} ml/dia`} cor="#b45309" />
                  )}
                  {sups.map(s => (
                    <NutriChip key={s.insumoId} label="Suplemento" value={`${s.ins.nome} · ${s.qtdDia} dose/dia`} cor="#7c2d12" />
                  ))}
                </div>
              )}

              {!temDieta && (
                <div style={{ fontSize: 12, color: 'var(--ink-3)', fontStyle: 'italic' }}>
                  Sem plano nutricional definido
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const NutriChip = ({ label, value, cor }) => (
  <div style={{
    background: cor + '12', border: '1px solid ' + cor + '30',
    borderRadius: 10, padding: '7px 11px', maxWidth: '100%',
  }}>
    <div style={{ fontSize: 9, color: cor, textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: 700 }}>
      {label}
    </div>
    <div style={{ fontSize: 13, color: 'var(--ink)', marginTop: 2, fontWeight: 500 }}>
      {value}
    </div>
  </div>
);
